body { font-family: system-ui; padding: 20px; }
.stage { position: relative; block-size: 180px; background: #0f172a; border-radius: 12px; overflow: hidden; }
.overlay { position: absolute; inset: 0; }
.tag { position: absolute; inset-block-start: 12px; inset-inline-start: 12px; background: #3b82f6; color: #fff; padding: 6px 10px; border-radius: 999px; }

body { font-family: system-ui; padding: 20px; }
.card {
  margin-top: 12px; margin-bottom: 12px;
  padding-left: 16px; padding-right: 16px;
  border-left: 5px solid #3b82f6;
  background: #f1f5f9; border-radius: 6px;
}

body { font-family: system-ui; padding: 20px; }
.card {
  margin-block: 12px;
  padding-inline: 16px;
  padding-block: 12px;
  border-inline-start: 5px solid #3b82f6;
  background: #f1f5f9; border-radius: 6px;
}

body { font-family: system-ui; padding: 20px; }
.panel {
  /* TODO: inline-size capped at 400px, centered, block-size 120px */
  background: #3b82f6; color: #fff; display: grid; place-items: center; border-radius: 10px;
}

body { font-family: system-ui; padding: 20px; }
.panel {
  inline-size: min(90%, 400px);
  block-size: 120px;
  margin-inline: auto;
  background: #3b82f6; color: #fff; display: grid; place-items: center; border-radius: 10px;
}

