.banner {
  position: relative;
  border-inline-start: 4px solid #3b82f6;
  padding-inline: 1rem;
  padding-block: 0.75rem;
  margin-block: 1rem;
}
.banner .close {
  position: absolute;
  inset-block-start: 0.5rem;
  inset-inline-end: 0.5rem;
}
